            }
            return left.compareTo(right);
        });
        return List.copyOf(policies.subList(0, Math.min(n, policies.size())));
    }

    private void removeFromIndexes(Claim claim) {
        byStatus.computeIfPresent(normalizeStatus(claim.status()), (key, count) -> count <= 1 ? null : count - 1);
        String policy = normalizePolicy(claim.policyNumber());
